functions._tiSlug:
function _tiSlug(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 30);
}

// 2026-05-23: subsection-marker detection — (a), (1), (i), (ii), bare
// letter, etc. Pure subsections need two pieces of special handling:
//   (1) Parenting: belong to the nearest non-subsection ancestor (the 6.1
//       above them, NOT the Article above 6.1).
//   (2) Bookmark naming: prefix parent's number so multiple (a)-style
//       subsections across different parents don't collide.
// _cleanHeader strips trailing `).:` so "(a)" arrives as "(a"; tolerate
// both forms.

functions._tiIsPureSubsectionNumber:
function _tiIsPureSubsectionNumber(n) {
  if (!n) return false;
  var inner = String(n).trim().replace(/^[\(\[]/, "").replace(/[\)\]]$/, "");
  if (!inner) return false;
  if (/^[a-z]$/i.test(inner)) return true;
  if (/^\d{1,3}$/.test(inner)) return true;
  if (/^[ivxlcdm]+$/i.test(inner)) return true;
  return false;
}

// Returns the prefix portion of a "5.1(a)"-style number, or null if not
// that pattern. "5.1(a)" → "5.1", "6(b)" → "6", "5.1.2(i)" → "5.1.2".

functions._tiDottedSubsectionPrefix:
function _tiDottedSubsectionPrefix(n) {
  if (!n) return null;
  var m = String(n).match(/^(\d+(?:\.\d+)*)\s*[\(\[]([a-z0-9ivxlcdm]+)\)?\s*$/i);
  return m ? m[1] : null;
}

// Custom XML part metadata layer (2026-05-23). Bookmark names are stable
// opaque IDs (ELI_SEC_<8 char>); title / number / parent / skip / etc.
// live in a Word custom XML part keyed by bookmark name. Eliminates the
// 40-char bookmark-name truncation entirely. The XML namespace is a
// FUNCTION (not a top-level var) because the bundler's per-function
// splitter would attach a stray top-level var to the previous function's
// body, breaking that function's eval.
// 2026-05-23: use http:// (not https://) namespace — some Word builds
// reject https URIs in custom XML namespace declarations.

functions._tiGenSectionId:
function _tiGenSectionId() {
  var chars = "abcdefghijklmnopqrstuvwxyz0123456789";
  var id = "";
  for (var i = 0; i < 8; i++) id += chars.charAt(Math.floor(Math.random() * chars.length));
  return id;
}

functions._tiXmlEsc:
function _tiXmlEsc(s) {
  return String(s == null ? "" : s)
    // Strip XML-illegal control characters (XML 1.0 spec disallows most
    // C0 control chars except tab, LF, CR). Word REJECTS attributes
    // containing these with InvalidArgument.
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, "")
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}

// 2026-05-23: no XML declaration, no whitespace between elements. Word's
// customXmlParts.add wants a clean XML fragment (Microsoft's own examples
// use single-line XML). The XML declaration + indented whitespace were
// likely the source of "InvalidArgument" rejection.

functions._tiBuildMetadataXml:
function _tiBuildMetadataXml(meta) {
  meta = meta || {};
  var xml = '<eli xmlns="' + _tiXmlNs() + '"';
  xml += ' v="1" lastModified="' + _tiXmlEsc(meta.lastModified || new Date().toISOString()) + '">';
  xml += '<sections>';
  var sections = meta.sections || {};
  Object.keys(sections).forEach(function (key) {
    var s = sections[key] || {};
    xml += '<section id="' + _tiXmlEsc(key) + '"';
    // ALWAYS write title attribute (even empty) so admin's intentional
    // empty-title edit can round-trip. Use "" sentinel rather than
    // omitting (which would otherwise revert to detector's title on rescan).
    xml += ' title="' + _tiXmlEsc(s.title == null ? "" : s.title) + '"';
    if (s.number) xml += ' number="' + _tiXmlEsc(s.number) + '"';
    if (s.parentId) xml += ' parentId="' + _tiXmlEsc(s.parentId) + '"';
    if (s.skip) xml += ' skip="true"';
    if (s.isManual) xml += ' isManual="true"';
    if (s.editedAt) xml += ' editedAt="' + _tiXmlEsc(s.editedAt) + '"';
    if (s.originalTitle) xml += ' originalTitle="' + _tiXmlEsc(s.originalTitle) + '"';
    // Persist range end as backup (the bookmark's actual range is the
    // source of truth, but if the bookmark gets clobbered externally
    // we can rebuild the range from this).
    if (s.endParagraphIdx != null) xml += ' endParaIdx="' + s.endParagraphIdx + '"';
    xml += '/>';
  });
  xml += '</sections></eli>';
  return xml;
}

functions._tiParseMetadataXml:
function _tiParseMetadataXml(xml) {
  if (!xml) return null;
  // Regex-based parse — namespace-immune (DOMParser's getElementsByTagName
  // doesn't reliably match namespaced elements across browsers). Our XML
  // schema is flat enough that regex is robust.
  try {
    var meta = { v: 1, sections: {} };
    var lastModMatch = String(xml).match(/lastModified="([^"]*)"/);
    if (lastModMatch) meta.lastModified = lastModMatch[1];
    var sectionRegex = /<section\b([^>]*?)\/?>/g;
    var m;
    while ((m = sectionRegex.exec(xml)) !== null) {
      var attrs = m[1];
      function _attr(name) {
        var mm = attrs.match(new RegExp('\\b' + name + '="([^"]*)"'));
        return mm ? _tiXmlUnesc(mm[1]) : null;
      }
      var id = _attr("id");
      if (!id) continue;
      var endParaIdxAttr = _attr("endParaIdx");
      meta.sections[id] = {
        title: _attr("title") || "",
        number: _attr("number") || "",
        parentId: _attr("parentId") || null,
        skip: _attr("skip") === "true",
        isManual: _attr("isManual") === "true",
        editedAt: _attr("editedAt") || null,
        originalTitle: _attr("originalTitle") || "",
        endParaIdx: endParaIdxAttr != null ? Number(endParaIdxAttr) : null,
      };
    }
    return meta;
  } catch (e) { return null; }
}

functions._tiXmlUnesc:
function _tiXmlUnesc(s) {
  if (s == null) return s;
  return String(s)
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&apos;/g, "'");
}

functions._tiReadMetadata:
function _tiReadMetadata() {
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    return Promise.resolve(null);
  }
  return window.eli.host.runRaw("template_indexer.read_metadata", function (ctx) {
    var parts = ctx.document.customXmlParts.getByNamespace(_tiXmlNs());
    parts.load("items");
    return ctx.sync().then(function () {
      if (!parts.items || !parts.items.length) return null;
      var xmlRes = parts.items[0].getXml();
      return ctx.sync().then(function () {
        return _tiParseMetadataXml(xmlRes.value || "");
      });
    });
  }).catch(function () { return null; });
}

// Dead _tiWriteMetadata removed — _tiWriteMetadataSafe is the only writer.
// (The dead one's delete+add in a single sync was the exact anti-pattern
// the safe writer documents as buggy on some Word builds.)

// 2026-05-23: strip "Article N" / "Exhibit A" / "Schedule 1" / "Appendix B"
// / "Annex II" prefix from a title — but ONLY when the section's own
// identifier doesn't match. For container headers themselves (own === id),
// the prefix is the legitimate title and we keep it. For sub-sections
// contaminated by legacy bookmark slugs, the prefix is duplication.

functions._tiStripContainerPrefix:
function _tiStripContainerPrefix(title, ownNumber) {
  if (!title) return title;
  var m = String(title).match(/^\s*(Article|Exhibit|Schedule|Appendix|Annex)\s+([A-Za-z0-9.]+)\s*[—\-:.]?\s*(.+)$/i);
  if (!m) return title;
  var prefixId = m[2];
  var rest = (m[3] || "").trim();
  if (!rest) return title; // nothing left after strip — keep original
  if (ownNumber && String(ownNumber) === prefixId) return title; // this section IS the container
  return rest;
}

// 2026-05-23: parse a bookmark name back into best-effort number + title.
// Reverse of _tiBookmarkName: walks the slug, treating short numeric /
// roman / single-letter parts as number components until it hits a real
// word (≥4 chars), then everything after is the title. Lossy (case, punct,
// spacing) but enough to preserve admin edits across Save → Rescan cycles.

functions._tiParseBookmarkName:
function _tiParseBookmarkName(name) {
  if (!name || typeof name !== "string" || name.indexOf("ELI_SEC_") !== 0) {
    return { number: "", title: "" };
  }
  var rest = name.slice("ELI_SEC_".length);
  if (!rest) return { number: "", title: "" };
  var parts = rest.split("_").filter(function (p) { return p.length > 0; });
  var numParts = [];
  var titleParts = [];
  var inTitle = false;
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i];
    var isNumericish = /^\d+$/.test(p) ||
      (/^[a-z]$/i.test(p) && numParts.length > 0) || // single letter only if following a number (subsection marker)
      /^[ivxlcdm]{2,3}$/i.test(p);
    if (!inTitle && isNumericish && p.length <= 3) {
      numParts.push(p);
    } else {
      inTitle = true;
      titleParts.push(p);
    }
  }
  var num = numParts.join(".");
  var title = titleParts.map(function (w) {
    return w.charAt(0).toUpperCase() + w.slice(1);
  }).join(" ");
  // No Article-N stripping here — that decision needs the section's own
  // number for context (parse doesn't have it). Done in the merge step
  // via _tiStripContainerPrefix(parsedTitle, h.number).
  return { number: num, title: title };
}

// 2026-05-23: detect visual separator paragraphs — runs of asterisks,
// dashes, dots, equals, bullets, etc. Common in legal templates ("* * *"
// between sections). These shouldn't count toward section content and
// should be visually distinct from real paragraphs.

functions._tiIsSeparator:
function _tiIsSeparator(text) {
  if (!text) return false;
  var trimmed = String(text).trim();
  if (!trimmed) return false;
  // Only separator characters (asterisks, dashes, dots, equals, bullets,
  // tildes, underscores, hash) and whitespace.
  if (!/^[\s\*\-•·=_~#\.]+$/.test(trimmed)) return false;
  // At least 3 non-whitespace chars so a single "." or "*" doesn't qualify.
  return trimmed.replace(/\s/g, "").length >= 3;
}

// 2026-05-23: detect a paragraph that's effectively just template logic
// — strip every {{...}} and [[...]] block plus whitespace/punctuation,
// and check if anything meaningful remains. True for paragraphs like
// "{{IF supplier_type == 'vendor'}}", "[[FOR each]]", "{{ENDIF}}" etc.
// These shouldn't be auto-bookmarked; admin can manually un-skip if they
// really want a bookmark on a control-flow paragraph.

functions._tiIsLogicOnly:
function _tiIsLogicOnly(text) {
  if (!text) return true;
  var stripped = String(text)
    .replace(/\{\{[\s\S]*?\}\}/g, "")
    .replace(/\[\[[\s\S]*?\]\]/g, "")
    .replace(/[\s.,;:!?\-_—–'"`]/g, "");
  return stripped.length === 0;
}

// 2026-05-23: bookmark naming. Word requires names to start with a letter
// (per CLAUDE.md anti-pattern: leading underscore → silent no-op) and
// caps length around 40 chars. Encodes both number and title in the
// name so admin / Office.js can see them via the Bookmark dialog —
// number-first because that's the navigation key admins think in.
// existing: { name: true } map of names already taken in this batch.

functions._tiBookmarkName:
function _tiBookmarkName(number, title, parentArticleNumber, existing) {
  existing = existing || {};
  // 2026-05-23: when section has no own number but lives under a parent
  // article that does (e.g. "Liability Cap" under Article 1), prefix with
  // the parent's number so the bookmark name reflects the document
  // structure: ELI_SEC_1_liability_cap, not ELI_SEC_liability_cap.
  // Also: pure paren subsections like (a)/(1)/(i) prepend parent's number
  // so (a) under 6.1 becomes ELI_SEC_6_1_a_<title> — unique across multiple
  // (a)-style subsections in the same doc.
  var num = number || "";
  var effectiveNumber;
  if (num && _tiIsPureSubsectionNumber(num) && parentArticleNumber) {
    effectiveNumber = parentArticleNumber + "_" + num;
  } else if (num) {
    effectiveNumber = num;
  } else {
    effectiveNumber = parentArticleNumber || "";
  }
  var numSlug = String(effectiveNumber).replace(/[^a-zA-Z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  var titleSlug = _tiSlug(title);
  // 2026-05-23: if base would exceed Word's 40-char bookmark limit AND
  // the title still has "Article N" redundant prefix, drop that prefix
  // from the slug to save space. Loses the "Article" word on round-trip
  // for very long titles, but preserves whole words (preferred over
  // truncating mid-word into "Intellectual Propert").
  function _buildBase(slug) {
    var b = "ELI_SEC_";
    if (numSlug) b += numSlug + "_";
    b += slug || "untitled";
    return b;
  }
  var base = _buildBase(titleSlug);
  // 2026-05-23: word-boundary truncation FIRST — prefer losing trailing
  // words to losing the meaningful "Article N" / "Exhibit A" prefix. Only
  // fall back to stripping the container prefix when even word-boundary
  // truncation can't fit (very long titles whose first preserved word
  // already overflows).
  function _wordBoundaryTruncate(b) {
    if (b.length <= 38) return b;
    var truncated = b.slice(0, 38);
    var lastUnderscore = truncated.lastIndexOf("_");
    var minTitleStart = "ELI_SEC_".length + (numSlug ? numSlug.length + 1 : 0);
    return (lastUnderscore > minTitleStart) ? truncated.slice(0, lastUnderscore) : truncated;
  }
  base = _wordBoundaryTruncate(base);
  // Last-resort: if word-boundary truncation produced something that's
  // ONLY the "ELI_SEC_<num>_<container>_<id>" stub (no actual title), try
  // stripping the container prefix from the title to save space.
  var minTitleStart2 = "ELI_SEC_".length + (numSlug ? numSlug.length + 1 : 0);
  var titlePart = base.slice(minTitleStart2);
  var stillJustContainer = /^(article|exhibit|schedule|appendix|annex)(_[a-z0-9]+)?$/i.test(titlePart);
  if (stillJustContainer && number) {
    var sp = new RegExp("^\\s*(?:Article|Exhibit|Schedule|Appendix|Annex)\\s+" + String(number).replace(/\./g, "\\.") + "\\s*[—\\-:.]?\\s*", "i");
    var shorterTitle = String(title || "").replace(sp, "").trim();
    if (shorterTitle && shorterTitle !== title) {
      base = _wordBoundaryTruncate(_buildBase(_tiSlug(shorterTitle)));
    }
  }
  var name = base;
  var n = 2;
  // 2026-05-23 BUG FIX: Word bookmark names allow only letters, digits,
  // and underscore — dash is REJECTED with InvalidArgument. Use underscore
  // for collision-resolved suffix instead. Symptom was "host.template_indexer.apply
  // failed: InvalidArgument" on Save when two sections sluggified to the
  // same base name (e.g. multiple "untitled" or two "(a)" definitions).
  while (existing[name]) {
    name = base.slice(0, 36) + "_" + n;
    if (name.length > 40) name = name.slice(0, 40);
    n++;
  }
  existing[name] = true;
  return name;
}

functions._tiScanSections:
function _tiScanSections() {
  if (!window.eli || !window.eli.host || typeof window.eli.host.readStructuralMap !== "function") {
    return Promise.reject(new Error("eli.host.readStructuralMap unavailable"));
  }
  return Promise.all([
    window.eli.host.readStructuralMap({ anchors: false, force: true }),
    _tiReadExistingBookmarks(),
    _tiReadSkipMarkers(),
    _tiReadMetadata(),
  ]).then(function (results) {
    var map = results[0];
    var loadedBookmarks = results[1] || [];
    var skipMarkers = results[2] || [];
    var metadata = results[3] || null;
    return _tiBuildScanResult(map, loadedBookmarks, skipMarkers, metadata);
  });
}

// Split out the scan-result builder so _tiBuildScanResult can be called
// with arbitrary map + bookmarks (used by Open Template too).

functions._tiBuildScanResult:
function _tiBuildScanResult(map, loadedBookmarks, skipMarkers, metadata) {
  return Promise.resolve().then(function () {
    if (!map || !Array.isArray(map.headers)) {
      return { headers: [], paragraphCount: 0 };
    }
    var existing = {};
    // 2026-05-23: pre-pass to compute parent article for each header.
    // Walk through headers in order. For each header at level N, parent
    // article is the most recent prior header at level < N. Carries
    // {number, title, level} so downstream rendering and bookmark naming
    // can prefix with parent context (e.g. unnumbered "Liability Cap"
    // under Article 1 → ELI_SEC_1_liability_cap + "↳ Article 1" badge).
    var _kernelHeaders = map.headers;
    // 2026-05-23 BUG FIX: original walk-by-level grabbed any lower-level
    // header as the parent, which incorrectly tagged "Definitions" as
    // belonging to "Recitals" when the doc structure was actually:
    //   RECITALS (level 0)
    //   ARTICLE 1 — DEFINITIONS (level 1)
    //   "Liability Cap" (level 2)
    // Recitals isn't an Article — it's a top-level non-Article header.
    // New rules:
    //   1. If current section's number is dotted (5.1.2), parent is the
    //      header with the prefix number (5.1) — exact number lookup.
    //   2. Otherwise, walk back to the nearest ARTICLE HEADER specifically
    //      (matches "Article N" pattern OR single-integer number ≤ 99).
    //      Skip non-Article headers like Recitals on the way back.
    function _isArticleHeader(h) {
      if (!h) return false;
      var title = String(h.title || h.text || "").trim();
      if (/^\s*Article\b/i.test(title)) return true;
      var num = String(h.number || "").trim();
      if (!num || num === "[Unnumbered]") return false;
      var cleanNum = num.replace(/[.\)\:]+$/, "");
      if (/^\d+$/.test(cleanNum) && Number(cleanNum) <= 99) return true;
      return false;
    }
    // 2026-05-23: exhibit-style container headers (Exhibit A, Schedule 1,
    // Appendix B, Annex II). Treated as valid parent containers — sections
    // detected AFTER an exhibit header belong to that exhibit (until the
    // next exhibit or until admin manually changes the parent).
    function _isExhibitHeader(h) {
      if (!h) return false;
      var title = String(h.title || h.text || "").trim();
      return /^\s*(Exhibit|Appendix|Schedule|Annex)\b/i.test(title);
    }
    function _isContainerHeader(h) {
      return _isArticleHeader(h) || _isExhibitHeader(h);
    }
    function _isExcludedFromParenting(h) {
      var title = String(h.title || h.text || "").trim().toLowerCase();
      return /^\s*(recitals?|whereas|witnesseth|preamble|now,?\s+therefore)\b/.test(title);
    }
    function _cleanHeader(h) {
      var n = String(h.number || "").trim();
      if (n === "[Unnumbered]") n = "";
      if (n) n = n.replace(/[.\)\:]+$/, "");
      var t = String(h.title || h.text || "").trim();
      if (!n) {
        var mm = t.match(/^\s*(\d+(?:\.\d+)*)[\.\)\s]+(.+)$/);
        if (mm) { n = mm[1]; t = mm[2].trim(); }
      }
      // 2026-05-23: when this is an exhibit-style header and the number
      // is still empty, parse "Exhibit A — Schedule of Fees" → number=A,
      // title="Schedule of Fees" so bookmark names + parent inheritance
      // work with the exhibit designator (ELI_SEC_A_payment_terms).
      if (!n) {
        var em = t.match(/^\s*(?:Exhibit|Appendix|Schedule|Annex)\s+([A-Z0-9]+)\s*[—\-:.\s]*(.*)$/i);
        if (em) { n = em[1]; t = (em[2] || "").trim() || t; }
      }
      return { number: n, title: t, level: h.level || 0 };
    }
    // 2026-05-23: returns { parent, parentIdx } so the section build can
    // also capture parent's kernel-header index — used to derive
    // parentSectionPidx (stable across title/number edits).
    function _parentForHeader(currentIdx) {
      var h = _kernelHeaders[currentIdx];
      var current = _cleanHeader(h);
      var currentLevel = h.level || 0;
      if (_isContainerHeader(h) && (!current.number || current.number.indexOf(".") === -1)) return null;
      var dotPrefix = _tiDottedSubsectionPrefix(current.number);
      if (dotPrefix) {
        for (var jp = currentIdx - 1; jp >= 0; jp--) {
          var pjp = _cleanHeader(_kernelHeaders[jp]);
          if (pjp.number === dotPrefix) return { parent: pjp, parentIdx: jp };
        }
      }
      if (_tiIsPureSubsectionNumber(current.number)) {
        for (var sk = currentIdx - 1; sk >= 0; sk--) {
          var psk = _kernelHeaders[sk];
          if (_isExcludedFromParenting(psk)) continue;
          var cleanSk = _cleanHeader(psk);
          if (_tiIsPureSubsectionNumber(cleanSk.number)) continue;
          return { parent: cleanSk, parentIdx: sk };
        }
        return null;
      }
      if (current.number && current.number.indexOf(".") !== -1) {
        var parentNum = current.number.split(".").slice(0, -1).join(".");
        for (var j = currentIdx - 1; j >= 0; j--) {
          var pj = _cleanHeader(_kernelHeaders[j]);
          if (pj.number === parentNum) return { parent: pj, parentIdx: j };
        }
      }
      for (var k = currentIdx - 1; k >= 0; k--) {
        var prev = _kernelHeaders[k];
        if (_isExcludedFromParenting(prev)) continue;
        if (_isContainerHeader(prev)) {
          return { parent: _cleanHeader(prev), parentIdx: k };
        }
        var prevLevel = prev.level || 0;
        if (currentLevel > 0 && prevLevel < currentLevel) {
          return { parent: _cleanHeader(prev), parentIdx: k };
        }
      }
      return null;
    }
    // 2026-05-23: full ancestry chain — walk parent → parent → root via
    // the parentIdx returned by _parentForHeader (no string matching).
    function _ancestryForHeader(currentIdx) {
      var chain = [];
      var info = _parentForHeader(currentIdx);
      var guard = 0;
      while (info && guard++ < 10) {
        chain.unshift(info.parent);
        info = _parentForHeader(info.parentIdx);
      }
      return chain;
    }
    var headers = map.headers.map(function (h, hIdx) {
      var num = String(h.number || "").trim();
      if (num === "[Unnumbered]") num = "";
      var ttl = String(h.title || h.text || "").trim();
      // Detection sometimes lumps the number into the title (e.g.,
      // "5.1 Limitation of Liability"). Split if number's missing AND
      // title leads with a dotted-digit sequence.
      if (!num) {
        var m = ttl.match(/^\s*(\d+(?:\.\d+)*)[\.\)\s]+(.+)$/);
        if (m) { num = m[1]; ttl = m[2].trim(); }
      }
      // 2026-05-23: strip "Article N" prefix from title — but ONLY when N
      // doesn't match this section's own number. Top-level Article headers
      // legitimately HAVE "Article N" in their title and we keep it. Only
      // sub-sections contaminated by legacy bookmarks get stripped.
      ttl = _tiStripContainerPrefix(ttl, num);
      // 2026-05-23: definitions truncation. Defined terms typically open
      // with a quoted phrase ("Liability Cap" means the maximum amount…)
      // but the whole paragraph gets pulled in as the heading text by
      // the detector. Truncate the title at the matching closing quote
      // so just the defined term is the section name. Handles straight
      // " and curly “”/‘’ quote pairs.
      var QUOTE_CLOSE = { '"': '"', '“': '”', '‘': '’', "'": "'" };
      var firstCh = ttl.charAt(0);
      if (QUOTE_CLOSE.hasOwnProperty(firstCh)) {
        var closeCh = QUOTE_CLOSE[firstCh];
        var closeIdx = ttl.indexOf(closeCh, 1);
        if (closeIdx > 0) ttl = ttl.slice(0, closeIdx + 1);
      }
      var parentInfo = _parentForHeader(hIdx);
      var parentArticle = parentInfo ? parentInfo.parent : null;
      // 2026-05-23: stable parent reference — the parent's paragraphIdx
      // (not its title/number) so re-naming Article 1 doesn't orphan its
      // children in the tree.
      var parentSectionPidx = parentInfo && _kernelHeaders[parentInfo.parentIdx]
        ? _kernelHeaders[parentInfo.parentIdx].idx
        : null;
      var ancestry = _ancestryForHeader(hIdx);
      // 2026-05-23: detect logic-only headers (paragraph is just
      // {{...}} / [[...]] markers). Per user, NOT auto-skipped — admin
      // decides manually. LOGIC chip stays visible so admin can spot
      // them at a glance.
      var rawText = String(h.text || h.title || "").trim();
      var isLogicOnly = _tiIsLogicOnly(rawText);
      return {
        paragraphIdx: h.idx,
        number: num,
        title: ttl || "(untitled)",
        level: h.level || 0,
        parentArticle: parentArticle,
        parentSectionPidx: parentSectionPidx,
        ancestry: ancestry,
