          if (missing.length) {
            insertErrors.push("missing after write: " + missing.slice(0, 3).join(", ") +
              (missing.length > 3 ? " (+ " + (missing.length - 3) + " more)" : ""));
          }
          return {
            written: actionLog.written.length,
            updated: actionLog.updated.length,
            cleared: actionLog.cleared.length,
            kept: actionLog.kept.length,
            actualCount: actualCount,
            missingCount: missing.length,
            errors: insertErrors,
            actions: actionLog,
          };
        });
      });
    });
  }).then(function (bookmarkResult) {
    // Separate metadata write — its own runRaw + Word.run. If this
    // fails (e.g. customXmlParts API not supported in this Word build),
    // bookmarks are still saved and we just report the metadata error.
    return _tiWriteMetadataSafe(metaPayload).then(function (metaResult) {
      bookmarkResult.metaWritten = metaResult.written;
      bookmarkResult.metaSectionCount = Object.keys(metaPayload.sections).length;
      if (metaResult.error) {
        bookmarkResult.errors = (bookmarkResult.errors || []).concat(["metadata: " + metaResult.error]);
      }
      return bookmarkResult;
    });
  });
}

// Safe metadata writer — wraps the whole Word.run in a try/catch promise
// chain so a Word-side InvalidArgument or unsupported-API error bubbles
// up as a reported warning, not a failure.

functions._tiWriteMetadataSafe:
function _tiWriteMetadataSafe(metaPayload) {
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    return Promise.resolve({ written: false, error: "host.runRaw unavailable" });
  }
  var newXml;
  try {
    newXml = _tiBuildMetadataXml(metaPayload);
  } catch (e) {
    return Promise.resolve({ written: false, error: "build_xml: " + (e && e.message || e) });
  }
  return window.eli.host.runRaw("template_indexer.write_metadata", function (ctx) {
    var xmlParts = ctx.document.customXmlParts.getByNamespace(_tiXmlNs());
    xmlParts.load("items");
    return ctx.sync().then(function () {
      var existingXmlRes = (xmlParts.items && xmlParts.items[0])
        ? xmlParts.items[0].getXml()
        : null;
      return ctx.sync().then(function () {
        var oldXml = existingXmlRes ? (existingXmlRes.value || "") : "";
        function _stripLastMod(s) { return String(s || "").replace(/lastModified="[^"]*"/, ""); }
        if (_stripLastMod(newXml) === _stripLastMod(oldXml)) {
          return { written: false, error: null };
        }
        // SEPARATE SYNC for delete — some Word builds reject delete+add
        // in the same batch with InvalidArgument.
        (xmlParts.items || []).forEach(function (p) {
          try { p.delete(); } catch (_e) {}
        });
        return ctx.sync().then(function () {
          // NOW the previous part is gone; add the new one in its own sync.
          ctx.document.customXmlParts.add(newXml);
          return ctx.sync().then(function () {
            return { written: true, error: null };
          });
        });
      });
    });
  }).catch(function (e) {
    return { written: false, error: (e && e.message) ? e.message : String(e) };
  });
}

functions._tiRenderRow:
function _tiRenderRow(s, idx, nextStartIdx, totalParagraphs) {
  var disabledCls = s.skip ? " _ti_row_skipped" : "";
  var bookmarkPreview = s.skip
    ? '<span style="color:#94a3b8;font-style:italic;">(skipped)</span>'
    : '<code class="_ti_bookmark_name">' + _tiEsc(s.bookmarkName) + '</code>';
  // 2026-05-23: pip now reads "L1"/"L2" instead of just "1"/"2" so it's
  // self-evident as a heading level. Same color coding by level.
  var levelLabel = "L" + (s.level || 0);
  var levelPip = '<span class="_ti_level_pip _ti_level_pip_' + (s.level || 0) + '" title="Heading level ' + (s.level || 0) + ' — 1=top (Article), 2=sub-section, 3=sub-sub, etc.">' + levelLabel + '</span>';
  // 2026-05-23: parent article badge — shows "↳ Article N — Title" when
  // this section lives under a higher-level header. Drives the user's
  // mental model that unnumbered subsections still inherit their parent.
  var parentBadge = "";
  // 2026-05-23: detect Exhibit-vs-Article for nicer labels in the
  // ancestry chain. An ancestor whose title leads with Exhibit/Schedule/
  // Appendix/Annex gets that prefix; otherwise it's an Article.
  function _ancestorLabel(a, isFirst) {
    if (!a) return "";
    var rawTitle = String(a.title || "");
    var typeMatch = rawTitle.match(/^\s*(Exhibit|Appendix|Schedule|Annex)\b/i);
    var num = a.number || "";
    if (typeMatch) {
      // Title already starts with the type — just use the title verbatim
      // (e.g. "Exhibit A — Schedule of Fees" stays whole).
      return rawTitle;
    }
    if (num && isFirst) return "Article " + num + (rawTitle ? " " + rawTitle : "");
    if (num) return num + (rawTitle ? " " + rawTitle : "");
    return rawTitle;
  }
  if (s.ancestry && s.ancestry.length) {
    var chainHtml = s.ancestry.map(function (a, i) {
      return '<span class="_ti_anc_link">' + _tiEsc(_ancestorLabel(a, i === 0)) + '</span>';
    }).join('<span class="_ti_anc_sep"> › </span>');
    parentBadge = '<div class="_ti_parent_article" title="Document hierarchy — full ancestry chain from top-level container down to immediate parent">↳ ' + chainHtml + '</div>';
  } else if (s.parentArticle) {
    var pLabel = _ancestorLabel(s.parentArticle, true);
    parentBadge = '<div class="_ti_parent_article" title="Section lives under this parent header in the document structure">↳ ' + _tiEsc(pLabel) + '</div>';
  }
  // 2026-05-23: paragraph range — makes the section\'s coverage explicit
  // so admin doesn\'t think paragraphs between section starts are being
  // skipped. They\'re body content of the section above.
  var endIdx = (typeof nextStartIdx === "number" ? nextStartIdx - 1 : totalParagraphs - 1);
  var paraRange = s.paragraphIdx === endIdx
    ? "paragraph " + s.paragraphIdx
    : "spans paragraphs " + s.paragraphIdx + "–" + endIdx;
  var logicBadge = s.logicOnly
    ? '<span class="_ti_logic_chip" title="Paragraph contains only template logic ({{...}} / [[...]]) — uncheck the box to skip if you don\'t want a bookmark here.">LOGIC</span>'
    : '';
  var manualBadge = s.isManual
    ? '<span class="_ti_manual_chip" title="Admin-created manual section — uses a range bookmark spanning paragraphs ' + s.paragraphIdx + '–' + s.endParagraphIdx + '">MANUAL</span>'
    : '';
  return '<div class="_ti_row' + disabledCls + (s.logicOnly ? ' _ti_row_logic' : '') + '" data-idx="' + idx + '">' +
    '<input type="checkbox" class="_ti_row_skip" data-act="toggle-skip" data-idx="' + idx + '"' + (s.skip ? "" : " checked") + ' title="' + (s.logicOnly ? "Auto-skipped: logic-only paragraph. Check the box if you want a bookmark here anyway." : "Uncheck to skip this section") + '">' +
    levelPip +
    '<div class="_ti_row_main">' +
      (parentBadge || logicBadge || manualBadge ? '<div class="_ti_parent_row">' + parentBadge + (logicBadge ? ' ' + logicBadge : '') + (manualBadge ? ' ' + manualBadge : '') + '</div>' : '') +
      '<div class="_ti_row_heading">' +
        '<div class="_ti_field_group">' +
          '<label class="_ti_field_label">Number</label>' +
          '<input type="text" class="_ti_input _ti_input_number" data-act="edit-number" data-idx="' + idx + '" value="' + _tiEsc(s.number) + '" placeholder="(none)" title="Section number — e.g. 5.1 — leave blank if unnumbered">' +
        '</div>' +
        '<div class="_ti_field_group">' +
          '<label class="_ti_field_label">Title</label>' +
          '<input type="text" class="_ti_input _ti_input_title" data-act="edit-title" data-idx="' + idx + '" value="' + _tiEsc(s.title) + '" placeholder="Section title" title="Section title">' +
        '</div>' +
      '</div>' +
      '<div class="_ti_row_meta">' +
        '<span class="_ti_meta_label">Bookmark (auto):</span> ' + bookmarkPreview +
        ' <span class="_ti_row_meta_dim">· ' + _tiEsc(paraRange) + '</span>' +
        ' <button class="_ti_row_locate" data-act="locate-row" data-idx="' + idx + '" title="Jump to this section in the open Word document">📍 Locate</button>' +
      '</div>' +
    '</div>' +
  '</div>';
}

// 2026-05-23: read existing ELI_SEC_* bookmarks from the live doc — uses
// Word.js bookmarks collection (always reflects in-memory state, including
// bookmarks just written via insertBookmark — body.getOoxml() lags). For
// each bookmark, loads its first + last paragraph's text, then matches
// against body.paragraphs to derive start/end paragraph indices. Text
// match is more reliable than compareLocationWith across Word builds.
// 2026-05-23: read bookmarks with a given prefix from the live doc.
// Uses Word.js bookmarks collection for names AND Word.js
// compareLocationWith for paragraph positions — guaranteed to align
// with body.paragraphs.items (same collection the structural map uses,
// so no drift between bookmark indices and detected-header indices).
// OOXML parsing previously caused drift in docs with content controls
// or other OOXML wrappers, leading to "duplicate" sections on rescan.
// OOXML-based bookmark read. Walks <w:p>, <w:bookmarkStart>, <w:bookmarkEnd>
// tokens in document order to compute each bookmark's start/end paragraph
// index. Replaces the prior compareLocationWith approach which hit two
// dead-ends: (1) it's O(N×M) — overflowed Office.js batch limits and
// returned [] silently on big docs; (2) Bookmark.getRange() doesn't exist
// in every Word build (this user's surface throws "bm.getRange is not a
// function" even though Word.js docs say 1.4+ has it).
// Single sync, parses ~200KB of XML in ~10ms, scales to thousands of
// bookmarks. Sanity-checks paragraph count against body.paragraphs.items
// so we surface alignment drift (e.g., from content-control wrappers).

functions._tiParseBookmarksFromOoxml:
function _tiParseBookmarksFromOoxml(ooxml, namePrefix) {
  var found = {};
  var idToName = {};
  var pIdx = -1;
  // body.getOoxml() returns the full package (pkg:package wrapper with
  // multiple pkg:parts — document.xml, header1.xml, footer1.xml, etc.).
  // Word's body.paragraphs only counts paragraphs in the BODY, not in
  // headers/footers/footnotes/endnotes — those live in sibling pkg:parts.
  // Extract just the <w:body>...</w:body> content so we walk the same
  // set of paragraphs Word's body.paragraphs sees.
  var bodyMatch = ooxml.match(/<w:body\b[^>]*>([\s\S]*?)<\/w:body>/);
  if (bodyMatch) {
    ooxml = bodyMatch[1];
  }
  // After narrowing to body, strip containers whose <w:p> elements still
  // appear in the body XML but are NOT counted by body.paragraphs:
  //   <w:txbxContent>     — text boxes / shapes (most common in templates)
  //   <mc:Fallback>       — alt-content fallback (older Word duplicates shape XML)
  //   <w:pict>            — legacy VML pictures with embedded paragraphs
  // [\s\S] (not .) so multi-line content matches; *? for non-greedy close.
  ooxml = ooxml
    .replace(/<w:txbxContent\b[^>]*>[\s\S]*?<\/w:txbxContent>/g, '')
    .replace(/<mc:Fallback\b[^>]*>[\s\S]*?<\/mc:Fallback>/g, '')
    .replace(/<w:pict\b[^>]*>[\s\S]*?<\/w:pict>/g, '');
  // Single regex with a capture group identifying which token we hit.
  // \b after the tag name prevents <w:pPr>, <w:bookmarkStart_> etc. from
  // matching. Match[1] tells us the tag: "p" | "bookmarkStart" | "bookmarkEnd".
  var tokenRe = /<w:(p|bookmarkStart|bookmarkEnd)\b[^>]*>/g;
  var m;
  while ((m = tokenRe.exec(ooxml)) !== null) {
    var tagName = m[1];
    var tok = m[0];
    if (tagName === "p") {
      pIdx++;
    } else if (tagName === "bookmarkStart") {
      var idMatch = tok.match(/w:id\s*=\s*"([^"]+)"/);
      var nameMatch = tok.match(/w:name\s*=\s*"([^"]+)"/);
      if (!idMatch || !nameMatch) continue;
      var name = nameMatch[1];
      if (namePrefix && name.indexOf(namePrefix) !== 0) continue;
      // pIdx is current paragraph at bookmarkStart. Clamp to 0 if before
      // first paragraph (rare — body-level bookmark).
      var sIdx = Math.max(0, pIdx);
      found[name] = { name: name, paragraphIdx: sIdx, endParagraphIdx: null, _id: idMatch[1] };
      idToName[idMatch[1]] = name;
    } else if (tagName === "bookmarkEnd") {
      var endIdMatch = tok.match(/w:id\s*=\s*"([^"]+)"/);
      if (!endIdMatch) continue;
      var endName = idToName[endIdMatch[1]];
      if (!endName || !found[endName]) continue;
      var entry = found[endName];
      var ePidx = Math.max(0, pIdx);
      // Only set endParagraphIdx for true range bookmarks (end > start).
      // Point bookmarks keep null so downstream treats them as single-para.
      if (ePidx > entry.paragraphIdx) {
        entry.endParagraphIdx = ePidx;
      }
    }
  }
  // pIdx + 1 = total paragraphs walked (pIdx is 0-indexed last paragraph).
  return { found: found, walkedParaCount: pIdx + 1 };
}

functions._tiReadBookmarksByPrefix:
function _tiReadBookmarksByPrefix(prefix) {
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    return Promise.resolve([]);
  }
  return window.eli.host.runRaw("template_indexer.read_bookmarks", function (ctx) {
    var body = ctx.document.body;
    var paragraphs = body.paragraphs;
    paragraphs.load("items");
    var ooxmlResult = body.getOoxml();
    return ctx.sync().then(function () {
      var ooxml = ooxmlResult.value || "";
      var paraCount = paragraphs.items.length;
      var parsed = _tiParseBookmarksFromOoxml(ooxml, prefix);
      // Sanity check: OOXML walk should count the same paragraph total
      // as body.paragraphs. If not, content-control wrappers or other
      // OOXML quirks are throwing off alignment; log only on diff > 1.
      // (+/-1 is almost always Word's trailing end-of-doc paragraph marker
      // which body.paragraphs ignores — benign for any bookmark not at the
      // very last paragraph. Larger diffs indicate an unaccounted-for
      // container leaking <w:p> into the walker count.)
      var paraDiff = Math.abs(parsed.walkedParaCount - paraCount);
      if (paraDiff > 1) {
        try {
          console.warn("[template_indexer] OOXML paragraph count mismatch — " +
            "walked=" + parsed.walkedParaCount + " bodyParas=" + paraCount +
            " (positions may be off by N for some bookmarks)");
          if (window.eli && window.eli.log && typeof window.eli.log.event === "function") {
            window.eli.log.event("template_indexer.ooxml_para_mismatch", {
              walked: parsed.walkedParaCount, bodyParas: paraCount, prefix: prefix,
            });
          }
        } catch (_e) {}
      }
      // Clamp paragraph indices to the live body's range. Protects against
      // the worst case where walker over-counts and a bookmark ends up
      // pointing at paragraphs.items[N] when N >= items.length (undefined).
      var maxIdx = Math.max(0, paraCount - 1);
      var result = Object.keys(parsed.found)
        .map(function (n) {
          var e = parsed.found[n];
          var pIdx = Math.min(e.paragraphIdx, maxIdx);
          var ePidx = (e.endParagraphIdx == null) ? null : Math.min(e.endParagraphIdx, maxIdx);
          return { name: n, paragraphIdx: pIdx, endParagraphIdx: ePidx };
        })
        .sort(function (a, b) { return a.paragraphIdx - b.paragraphIdx; });
      return result;
    });
  }).catch(function (err) {
    try {
      if (window.eli && window.eli.log && typeof window.eli.log.event === "function") {
        window.eli.log.event("template_indexer.read_bookmarks_failed", {
          prefix: prefix, message: err && err.message || String(err),
        });
      }
      console.error("[template_indexer] read_bookmarks failed:", err);
    } catch (_e) {}
    return [];
  });
}

functions._tiReadSkipMarkers:
function _tiReadSkipMarkers() {
  return _tiReadBookmarksByPrefix("ELI_SKIP_");
}

// 2026-05-23: clear all ELI_SEC_* bookmarks from the open doc — wipes
// the doc's index without re-applying. Used by "Clear & Restart" to
// give admin a clean slate. Returns {cleared: N} on success.

functions._tiClearAllBookmarks:
function _tiClearAllBookmarks() {
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    return Promise.reject(new Error("eli.host.runRaw unavailable"));
  }
  return window.eli.host.runRaw("template_indexer.clear", function (ctx) {
    var bookmarks = ctx.document.bookmarks;
    bookmarks.load("items/name");
    var xmlParts = ctx.document.customXmlParts.getByNamespace(_tiXmlNs());
    xmlParts.load("items");
    return ctx.sync().then(function () {
      var cleared = 0;
      bookmarks.items.forEach(function (bm) {
        if (!bm.name) return;
        if (bm.name.indexOf("ELI_SEC_") === 0 || bm.name.indexOf("ELI_SKIP_") === 0) {
          try { bm.delete(); cleared++; } catch (_e) {}
        }
      });
      (xmlParts.items || []).forEach(function (p) {
        try { p.delete(); } catch (_e) {}
      });
      return ctx.sync().then(function () { return { cleared: cleared }; });
    });
  });
}

// 2026-05-23: Locate single paragraph — selects that one paragraph.
// Used by paragraph-row 📍. Section rows use _tiLocateSection (full range).

functions._tiLocateParagraph:
function _tiLocateParagraph(paragraphIdx) {
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    if (typeof showToast === "function") showToast("Word host not available", "err");
    return;
  }
  window.eli.host.runRaw("template_indexer.locate", function (ctx) {
    var paragraphs = ctx.document.body.paragraphs;
    ctx.load(paragraphs, "items");
    return ctx.sync().then(function () {
      if (paragraphIdx < 0 || paragraphIdx >= paragraphs.items.length) {
        throw new Error("paragraph_out_of_range");
      }
      paragraphs.items[paragraphIdx].select();
      return ctx.sync();
    });
  }).then(function () {
    if (typeof showToast === "function") {
      showToast("✓ Selected ¶" + paragraphIdx + " in document", "ok");
    }
  }).catch(function (err) {
    if (typeof showToast === "function") {
      showToast("Locate failed: " + (err && err.message || "unknown"), "err");
    }
  });
}

// 2026-05-23: Locate whole section — selects the bookmark's full range
// so admin sees the section's COMPLETE extent (header through end) in
// Word. Falls back to paragraph + endParagraphIdx range if the bookmark
// isn't yet in the doc (unsaved new section).

functions._tiLocateSection:
function _tiLocateSection(section) {
  if (!section) return;
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    if (typeof showToast === "function") showToast("Word host not available", "err");
    return;
  }
  var bookmarkName = section.bookmarkName;
  var startIdx = section.paragraphIdx;
  var endIdx = (typeof section.endParagraphIdx === "number") ? section.endParagraphIdx : null;
  window.eli.host.runRaw("template_indexer.locate_section", function (ctx) {
    // Always select via paragraph range. Bookmark.getRange() doesn't
    // exist on every Word build, and we always have a valid paragraphIdx
    // (+ endParagraphIdx from metadata) on the section so we don't need
    // the bookmark proxy anyway.
    var paragraphs = ctx.document.body.paragraphs;
    paragraphs.load("items");
    return ctx.sync().then(function () {
      if (startIdx < 0 || startIdx >= paragraphs.items.length) {
        throw new Error("paragraph_out_of_range");
      }
      if (endIdx != null && endIdx > startIdx && endIdx < paragraphs.items.length) {
        var startP = paragraphs.items[startIdx];
        var endP = paragraphs.items[endIdx];
        startP.getRange("Start").expandTo(endP.getRange("End")).select();
      } else {
        paragraphs.items[startIdx].select();
      }
      return ctx.sync().then(function () { return { mode: "range" }; });
    });
  }).then(function (r) {
    if (typeof showToast === "function") {
      var lbl = (section.number ? section.number + " " : "") + (section.title || "section");
      var rangeStr = (endIdx != null && endIdx > startIdx) ? "¶" + startIdx + "–¶" + endIdx : "¶" + startIdx;
      showToast("✓ Selected " + lbl + " (" + rangeStr + ") in document", "ok");
    }
  }).catch(function (err) {
    if (typeof showToast === "function") {
      showToast("Locate failed: " + (err && err.message || "unknown"), "err");
    }
  });
}

functions.showTemplateIndexer:
function showTemplateIndexer() {
  var out = window.eli && window.eli.ui && window.eli.ui.claimOutput
    ? window.eli.ui.claimOutput()
    : document.getElementById("output");
  if (!out) return;
  out.classList.add("eli-view-enter");
  out.innerHTML =
    '<div class="_ti_root">' +
      '<div class="_ti_header">' +
        '<div>' +
          '<div class="_ti_header_eyebrow">ADMIN — RESTRICTED</div>' +
          '<div class="_ti_header_title">🔖 Template Indexer</div>' +
          '<div class="_ti_header_sub" id="_ti_status">Scanning current document…</div>' +
        '</div>' +
        '<div class="_ti_header_btns">' +
          '<span class="_ti_dirty_indicator" id="_ti_dirty_indicator" style="display:none;">● Unsaved changes — click Save &amp; Apply</span>' +
          '<button class="_ti_btn _ti_btn_platinum" id="_ti_open_template" title="Pick a template from your bd_templates library and load it into Word for indexing">📂 Open Template…</button>' +
          '<button class="_ti_btn _ti_btn_danger" id="_ti_clear_restart" title="Delete every ELI_SEC_* bookmark from the open doc AND re-run detection from scratch">🗑 Clear &amp; Restart</button>' +
          '<button class="_ti_btn _ti_btn_platinum" id="_ti_rescan" title="Re-run section detection — preserves existing ELI_SEC_* bookmarks (loads them as prior map)">↻ Re-scan</button>' +
          '<button class="_ti_btn _ti_btn_platinum" id="_ti_preview_export" title="Preview the map exactly as downstream tools (Template Searcher, Build Draft, etc.) will see it">👁 Preview Export</button>' +
          '<button class="_ti_btn _ti_btn_gold" id="_ti_apply" disabled>💾 Save &amp; Apply</button>' +
        '</div>' +
      '</div>' +
      '<div class="_ti_explainer">' +
        '<b>Workflow:</b> ' +
        '<b style="color:#0d1b2a;">①</b> Edit section numbers/titles inline below, uncheck sections you don\'t want indexed. ' +
        '<b style="color:#0d1b2a;">②</b> Click <b>💾 Save &amp; Apply</b> to write the bookmarks into the Word doc. ' +
        '<b style="color:#0d1b2a;">③</b> Save the Word doc itself (Ctrl+S). ' +
        '<b style="color:#0d1b2a;">④</b> Re-upload via <b>Build Draft → Settings</b> so the indexed template lands in IDB for template_searcher and other tools to use.' +
      '</div>' +
      '<div class="_ti_body" id="_ti_body">' +
        '<div class="_ti_loading"><span class="_ti_spinner"></span>Reading section structure from <code>eli.host.readStructuralMap</code>…</div>' +
      '</div>' +
    '</div>';
  var state = {
    sections: [],
    paragraphs: [],
    selectedParagraphs: {},
    // 2026-05-23: section selection for bulk re-parent — keyed by
    // section.paragraphIdx (stable across splice/sort) so the selection
    // survives re-renders.
    selectedSections: {},
    // 2026-05-23: paragraphs the admin ✕ Removed. Persisted across
    // Re-scan via ELI_SKIP_<paraIdx> bookmarks written on Save & Apply.
    // Without this, the detector would re-create the section on every
    // scan because the doc paragraph still looks like a header.
    removedParagraphs: {},
    lastSelectedIdx: null,
    showAllParagraphs: false,
    scannedAt: 0,
    paragraphCount: 0,
    // 2026-05-23: dirty tracking — toggled true on any edit
    // (skip toggle, number/title input, remove, manual group), cleared
    // after a successful Apply. Drives the "Unsaved changes" indicator.
    dirty: false,
    lastApply: null,
  };
  function _markDirty() {
    state.dirty = true;
    _updateDirtyIndicator();
  }
  // 2026-05-23: defensive — sort state.sections by paragraphIdx so the
  // map is always in document order no matter what mutation just ran
  // (Remove, Move, Group, manual insert). Called from every state-changing
  // path so the user never sees the map out of order.
  function _sortSections() {
    state.sections.sort(function (a, b) {
      return (a.paragraphIdx || 0) - (b.paragraphIdx || 0);
    });
  }
  function _clearDirty() {
    state.dirty = false;
    _updateDirtyIndicator();
  }
  function _updateDirtyIndicator() {
    var ind = out && out.querySelector("#_ti_dirty_indicator");
