    newWrap.querySelectorAll("._ti_pgroup").forEach(function (g) {
      var key = g.getAttribute("data-pgroup-key");
      if (key in openMap) g.open = openMap[key];
    });
  }
  // 2026-05-23: Move-paragraph-to-section popover. Anchored to the ↪ Move
  // button on the clicked paragraph row, lists every section whose start
  // is at or before this paragraph (can't move a paragraph earlier than
  // a section's existing start without changing the section's meaning).
  // Picking a target extends that section's range and marks it manual,
  // then the two-pass _sectionForParagraph lookup pulls the paragraph
  // (and everything between the section's start and this paragraph) under
  // the chosen section's group on next render.
  function _showMoveParagraphPopover(pidx, anchorEl) {
    _closeMovePopover();
    if (typeof pidx !== "number" || isNaN(pidx)) return;
    var currentSectionIdx = -1;
    var found = null;
    // Inline lookup (function scope) — mirrors _sectionForParagraph in
    // the enclosing _tiScanSections closure but state.sections is what
    // we work against here.
    for (var mi = state.sections.length - 1; mi >= 0; mi--) {
      var ms = state.sections[mi];
      if (!ms.isManual || typeof ms.endParagraphIdx !== "number") continue;
      if (pidx >= ms.paragraphIdx && pidx <= ms.endParagraphIdx) { found = { section: ms, idx: mi }; break; }
    }
    if (!found) {
      for (var i = state.sections.length - 1; i >= 0; i--) {
        var s = state.sections[i];
        if (s.isManual) continue;
        if (pidx < s.paragraphIdx) continue;
        var sEnd = state.paragraphCount - 1;
        for (var j = i + 1; j < state.sections.length; j++) {
          if (!state.sections[j].isManual) { sEnd = state.sections[j].paragraphIdx - 1; break; }
        }
        if (pidx <= sEnd) { found = { section: s, idx: i }; break; }
      }
    }
    if (found) currentSectionIdx = found.idx;
    var candidates = [];
    state.sections.forEach(function (sec, idx) {
      if (sec.paragraphIdx > pidx) return;
      candidates.push({ section: sec, idx: idx });
    });
    if (!candidates.length) {
      if (typeof showToast === "function") showToast("No sections start at or before paragraph " + pidx, "warn");
      return;
    }
    var pop = document.createElement("div");
    pop.className = "_ti_move_popover";
    pop.id = "_ti_move_popover_active";
    var listHtml = candidates.map(function (c) {
      var sec = c.section;
      var isCurrent = c.idx === currentSectionIdx;
      var label = (sec.number ? sec.number + " — " : "") + (sec.title || "(untitled)");
      var manualBadge = sec.isManual ? '<span class="_ti_mvp_chip">M</span>' : '';
      var startNote = '<span class="_ti_mvp_start">¶' + sec.paragraphIdx + '</span>';
      return '<button class="_ti_mvp_item' + (isCurrent ? ' _ti_mvp_current' : '') + '" data-section-idx="' + c.idx + '"' +
        (isCurrent ? ' disabled title="Paragraph is already in this section"' : ' title="Move paragraph ' + pidx + ' into this section"') + '>' +
        startNote + _tiEsc(label) + manualBadge +
        (isCurrent ? ' <span class="_ti_mvp_current_tag">(current)</span>' : '') +
        '</button>';
    }).join("");
    pop.innerHTML =
      '<div class="_ti_mvp_head">↪ Move paragraph <b>' + pidx + '</b> to…' +
        '<button class="_ti_mvp_close" type="button" title="Close">✕</button>' +
      '</div>' +
      '<div class="_ti_mvp_list">' + listHtml + '</div>' +
      '<div class="_ti_mvp_foot">Target section\'s range will extend to include ¶' + pidx +
        ', and the section becomes a range bookmark spanning its current start through ¶' + pidx + '.</div>';
    var rect = anchorEl.getBoundingClientRect();
    pop.style.position = "fixed";
    var leftPx = Math.max(8, Math.min(rect.right - 320, window.innerWidth - 340));
    var topPx = rect.bottom + 4;
    if (topPx + 320 > window.innerHeight) topPx = Math.max(8, rect.top - 324);
    pop.style.top = topPx + "px";
    pop.style.left = leftPx + "px";
    document.body.appendChild(pop);
    pop.addEventListener("click", function (ev2) {
      var closeBtn = ev2.target.closest && ev2.target.closest("._ti_mvp_close");
      if (closeBtn) { _closeMovePopover(); return; }
      var btn = ev2.target.closest && ev2.target.closest("button[data-section-idx]");
      if (!btn || btn.disabled) return;
      var targetIdx = Number(btn.getAttribute("data-section-idx"));
      var target = state.sections[targetIdx];
      if (!target) { _closeMovePopover(); return; }
      // 2026-05-23: Move only extends the explicit range — does NOT set
      // isManual. The section keeps its detected identity (no MANUAL chip).
      // _sectionForParagraph keys off endParagraphIdx, not isManual, so the
      // extended range still wins over implicit-range neighbors.
      var prevEnd = (typeof target.endParagraphIdx === "number") ? target.endParagraphIdx : target.paragraphIdx;
      target.endParagraphIdx = Math.max(prevEnd, pidx);
      _sortSections();
      _refreshBookmarkNames();
      _markDirty();
      _closeMovePopover();
      _renderBody();
      if (typeof showToast === "function") {
        var lbl = (target.number ? target.number + " " : "") + (target.title || "section");
        showToast("✓ Paragraph " + pidx + " moved to " + lbl, "ok");
      }
    });
    setTimeout(function () {
      document.addEventListener("mousedown", _movePopoverOutside, true);
      document.addEventListener("keydown", _movePopoverEsc, true);
    }, 0);
  }
  function _movePopoverOutside(ev2) {
    var pop = document.getElementById("_ti_move_popover_active");
    if (pop && !pop.contains(ev2.target)) _closeMovePopover();
  }
  function _movePopoverEsc(ev2) {
    if (ev2.key === "Escape") _closeMovePopover();
  }
  function _closeMovePopover() {
    document.removeEventListener("mousedown", _movePopoverOutside, true);
    document.removeEventListener("keydown", _movePopoverEsc, true);
    var pop = document.getElementById("_ti_move_popover_active");
    if (pop && pop.parentNode) pop.parentNode.removeChild(pop);
  }

  // 2026-05-23: single-section Move popover — anchored to the ↪ button on
  // a section summary, lists every section starting before this one +
  // "(top level)". Picking re-parents this section (same logic as the
  // per-section "Belongs to" dropdown in the body, but without needing
  // to expand the section first).
  function _showMoveSectionPopover(sectionPidx, anchorEl) {
    _closeMovePopover();
    var sec = null, sectionIdx = -1;
    for (var i = 0; i < state.sections.length; i++) {
      if (state.sections[i].paragraphIdx === sectionPidx) {
        sec = state.sections[i];
        sectionIdx = i;
        break;
      }
    }
    if (!sec) return;
    // Determine current parent (by matching number + title against state.sections).
    var currentParentPidx = null;
    if (sec.parentArticle) {
      for (var j = 0; j < state.sections.length; j++) {
        var ps = state.sections[j];
        if (ps === sec) continue;
        if ((ps.number || "") === (sec.parentArticle.number || "") &&
            (ps.title || "") === (sec.parentArticle.title || "") &&
            ps.paragraphIdx < sec.paragraphIdx) {
          if (currentParentPidx === null || ps.paragraphIdx > currentParentPidx) {
            currentParentPidx = ps.paragraphIdx;
          }
        }
      }
    }
    // Candidate list: top-level + every section starting before this one
    // (parent must come first in doc order).
    var candidates = [];
    state.sections.forEach(function (s, idx) {
      if (s === sec) return;
      if (s.paragraphIdx >= sec.paragraphIdx) return;
      candidates.push({ section: s, idx: idx });
    });
    var pop = document.createElement("div");
    pop.className = "_ti_move_popover";
    pop.id = "_ti_move_popover_active";
    var topIsCurrent = !sec.parentArticle;
    var topBtn = '<button class="_ti_mvp_item' + (topIsCurrent ? ' _ti_mvp_current' : '') +
      '" data-section-idx="-1"' + (topIsCurrent ? ' disabled' : '') + '>' +
      '<span class="_ti_mvp_start">—</span>(top level — no parent)' +
      (topIsCurrent ? ' <span class="_ti_mvp_current_tag">(current)</span>' : '') +
      '</button>';
    var listHtml = topBtn + candidates.map(function (c) {
      var s2 = c.section;
      var isCurrent = currentParentPidx === s2.paragraphIdx;
      var label = (s2.number ? s2.number + " — " : "") + (s2.title || "(untitled)");
      var startNote = '<span class="_ti_mvp_start">¶' + s2.paragraphIdx + '</span>';
      return '<button class="_ti_mvp_item' + (isCurrent ? ' _ti_mvp_current' : '') + '" data-section-idx="' + c.idx +
        '"' + (isCurrent ? ' disabled' : '') + '>' +
        startNote + _tiEsc(label) +
        (isCurrent ? ' <span class="_ti_mvp_current_tag">(current)</span>' : '') +
        '</button>';
    }).join("");
    var secLbl = (sec.number ? sec.number + " " : "") + (sec.title || "(untitled)");
    pop.innerHTML =
      '<div class="_ti_mvp_head">↪ Move "' + _tiEsc(secLbl) + '" to belong under…' +
        '<button class="_ti_mvp_close" type="button" title="Close">✕</button>' +
      '</div>' +
      '<div class="_ti_mvp_list">' + listHtml + '</div>' +
      '<div class="_ti_mvp_foot">Sets the section\'s parent. It will re-indent under the chosen target in the map + its bookmark name will gain the new parent\'s number prefix.</div>';
    var rect = anchorEl.getBoundingClientRect();
    pop.style.position = "fixed";
    var leftPx = Math.max(8, Math.min(rect.right - 320, window.innerWidth - 340));
    var topPx = rect.bottom + 4;
    if (topPx + 320 > window.innerHeight) topPx = Math.max(8, rect.top - 324);
    pop.style.top = topPx + "px";
    pop.style.left = leftPx + "px";
    document.body.appendChild(pop);
    pop.addEventListener("click", function (ev2) {
      var closeBtn = ev2.target.closest && ev2.target.closest("._ti_mvp_close");
      if (closeBtn) { _closeMovePopover(); return; }
      var btn = ev2.target.closest && ev2.target.closest("button[data-section-idx]");
      if (!btn || btn.disabled) return;
      var pickedIdx = Number(btn.getAttribute("data-section-idx"));
      var newParent = (pickedIdx >= 0) ? state.sections[pickedIdx] : null;
      if (newParent) {
        sec.parentArticle = {
          number: newParent.number || "",
          title: newParent.title || "",
          level: newParent.level || 0,
        };
        sec.parentSectionPidx = newParent.paragraphIdx;
        sec.ancestry = (newParent.ancestry || []).concat([{
          number: newParent.number || "",
          title: newParent.title || "",
        }]);
        sec.level = (newParent.level || 0) + 1;
      } else {
        sec.parentArticle = null;
        sec.parentSectionPidx = null;
        sec.ancestry = [];
        sec.level = 1;
      }
      _refreshBookmarkNames();
      _markDirty();
      _closeMovePopover();
      _renderBody();
      var newEl = bodyEl.querySelector('._ti_pgroup[data-section-pidx="' + sec.paragraphIdx + '"]');
      if (newEl) newEl.open = true;
      if (typeof showToast === "function") {
        var lbl = newParent
          ? (newParent.number ? newParent.number + " " : "") + (newParent.title || "section")
          : "top level (no parent)";
        showToast("✓ " + secLbl + " now belongs to " + lbl, "ok");
      }
    });
    setTimeout(function () {
      document.addEventListener("mousedown", _movePopoverOutside, true);
      document.addEventListener("keydown", _movePopoverEsc, true);
    }, 0);
  }

  // 2026-05-23: unified bulk Move Selected — handles paragraphs, sections,
  // or both. Paragraphs move INTO the chosen target (target's range extends
  // forward to include them). Sections RE-PARENT to the chosen target
  // (or "top level"). Eligible target satisfies both constraints when both
  // are selected.
  function _showBulkMoveSelectionDialog() {
    var selPids = Object.keys(state.selectedParagraphs).map(Number).sort(function (a, b) { return a - b; });
    var selSecPidxs = Object.keys(state.selectedSections).map(Number);
    var hasParaSel = selPids.length > 0;
    var hasSecSel = selSecPidxs.length > 0;
    if (!hasParaSel && !hasSecSel) {
      if (typeof showToast === "function") showToast("Select at least one paragraph or section first", "warn");
      return;
    }
    var minParaPidx = hasParaSel ? selPids[0] : Infinity;
    var maxParaPidx = hasParaSel ? selPids[selPids.length - 1] : -Infinity;
    var minSecPidx = hasSecSel ? Math.min.apply(null, selSecPidxs) : Infinity;
    // Build candidate list.
    //   "top level" valid for sections only — skip when paragraphs are
    //   also selected (paragraphs need a real target section to land in).
    var candidates = [];
    if (hasSecSel && !hasParaSel) {
      candidates.push({ section: null, idx: -1, label: "(top level — no parent)" });
    }
    state.sections.forEach(function (sec, idx) {
      // Section-reparent constraints: target can't be one of the selected
      // sections (would create a cycle), and must start strictly BEFORE
      // the earliest selected section.
      if (hasSecSel && selSecPidxs.indexOf(sec.paragraphIdx) !== -1) return;
      if (hasSecSel && sec.paragraphIdx >= minSecPidx) return;
      // Paragraph-move constraint: target must start at or before the
      // earliest selected paragraph (so its range can extend forward).
      if (hasParaSel && sec.paragraphIdx > minParaPidx) return;
      candidates.push({ section: sec, idx: idx });
    });
    if (!candidates.length) {
      if (typeof showToast === "function") {
        showToast("No sections satisfy the move constraints for your selection", "warn");
      }
      return;
    }
    // Title + subtitle reflect what's selected.
    var titleParts = [];
    if (hasParaSel) titleParts.push(selPids.length + " paragraph" + (selPids.length === 1 ? "" : "s"));
    if (hasSecSel) titleParts.push(selSecPidxs.length + " section" + (selSecPidxs.length === 1 ? "" : "s"));
    var subtitleParts = [];
    if (hasParaSel) {
      subtitleParts.push("Paragraphs <b>¶" + minParaPidx + "</b>" + (selPids.length > 1 ? "–<b>¶" + maxParaPidx + "</b>" : "") +
        " will be moved into the chosen section (its range extends to include ¶" + maxParaPidx + ").");
    }
    if (hasSecSel) {
      subtitleParts.push(selSecPidxs.length + " selected section" + (selSecPidxs.length === 1 ? "" : "s") +
        " will be re-parented to the chosen target (re-indented in the map).");
    }
    _showSectionPickerDialog({
      title: "↪ Move selected " + titleParts.join(" + "),
      subtitle: subtitleParts.join(" "),
      candidates: candidates,
      confirmLabel: "↪ Apply move",
      onConfirm: function (targetIdx) {
        var target = (targetIdx >= 0) ? state.sections[targetIdx] : null;
        var changed = 0;
        // Section re-parent (top-level OK when only sections selected).
        if (hasSecSel) {
          var newParentArticle = target
            ? { number: target.number || "", title: target.title || "", level: target.level || 0 }
            : null;
          var newAncestry = target
            ? (target.ancestry || []).concat([{ number: target.number || "", title: target.title || "" }])
            : [];
          var newLevel = target ? ((target.level || 0) + 1) : 1;
          selSecPidxs.forEach(function (spidx) {
            var sec = null;
            for (var i = 0; i < state.sections.length; i++) {
              if (state.sections[i].paragraphIdx === spidx) { sec = state.sections[i]; break; }
            }
            if (!sec) return;
            sec.parentArticle = newParentArticle ? Object.assign({}, newParentArticle) : null;
            sec.parentSectionPidx = target ? target.paragraphIdx : null;
            sec.ancestry = newAncestry.slice();
            sec.level = newLevel;
            changed++;
          });
        }
        // Paragraph move — extend target's range forward.
        if (hasParaSel && target) {
          var prevEnd = (typeof target.endParagraphIdx === "number") ? target.endParagraphIdx : target.paragraphIdx;
          target.endParagraphIdx = Math.max(prevEnd, maxParaPidx);
          changed++;
        }
        _sortSections();
        _refreshBookmarkNames();
        _markDirty();
        state.selectedParagraphs = {};
        state.selectedSections = {};
        state.lastSelectedIdx = null;
        _renderBody();
        if (typeof showToast === "function") {
          var lbl = target
            ? (target.number ? target.number + " " : "") + (target.title || "section")
            : "top level (no parent)";
          var moved = [];
          if (hasParaSel) moved.push(selPids.length + " ¶" + (selPids.length === 1 ? "" : "s"));
          if (hasSecSel) moved.push(selSecPidxs.length + " section" + (selSecPidxs.length === 1 ? "" : "s"));
          showToast("✓ Moved " + moved.join(" + ") + " to " + lbl, "ok");
        }
      },
    });
  }

  // 2026-05-23: Open Template dialog — uses build_draft's dispatch
  // handlers (listTemplates + loadTemplateRaw) so we get the exact same
  // template load pipeline Build Draft uses: handles JSON-wrapped content,
  // skeleton markers, section-aware H/F, font preservation, bisection
  // fallback on malformed OOXML. Reimplementing via raw insertOoxml threw
  // GeneralException for any non-trivial template.
  // Preview Export — shows exactly what downstream tools (template_searcher,
  // build_draft, ask_eli, anything that reads ELI_SEC_* bookmarks) will see
  // after Save & Apply. Two views: a nested tree for human review + a raw
  // JSON payload for programmatic consumption. JSON shape mirrors what
  // _tiApplyBookmarks writes to the custom XML part PLUS the bookmark
  // positions, so consumers don't have to re-scan the doc to use it.
  function _showPreviewExportDialog() {
    var DIALOG_ID = "_ti_preview_export_" + Date.now();
    var active = state.sections.filter(function (s) { return !s.skip; });
    // Build the JSON payload that mirrors metadata + live positions.
    var sectionsByPidx = {};
    state.sections.forEach(function (s) {
      if (s.bookmarkName) sectionsByPidx[s.paragraphIdx] = s;
    });
    function _parentBmName(s) {
      if (s.parentSectionPidx == null) return null;
      var parent = sectionsByPidx[s.parentSectionPidx];
      if (!parent) return null;
      // Walk past skipped ancestors (matches _resolveLivingParentId in apply).
      var guard = 0;
      while (parent && guard++ < 20) {
        if (!parent.skip && parent.bookmarkName) return parent.bookmarkName;
        if (parent.parentSectionPidx == null) return null;
        parent = sectionsByPidx[parent.parentSectionPidx];
      }
      return null;
    }
    var jsonPayload = {
      schemaVersion: 1,
      generatedAt: new Date().toISOString(),
      tool: "template_indexer",
      sectionCount: active.length,
      sections: active.map(function (s) {
        return {
          bookmarkName: s.bookmarkName,
          number: s.number || "",
          title: s.title == null ? "" : s.title,
          paragraphIdx: s.paragraphIdx,
          endParagraphIdx: (typeof s.endParagraphIdx === "number") ? s.endParagraphIdx : null,
          parentBookmarkName: _parentBmName(s),
          isManual: !!s.isManual,
          level: s.level || (s.parentSectionPidx == null ? 0 : 1),
        };
      }),
    };
    // Build the nested tree (children grouped under parents).
    var childrenByParent = {};
    active.forEach(function (s) {
      var key = s.parentSectionPidx == null ? "_top" : s.parentSectionPidx;
      (childrenByParent[key] = childrenByParent[key] || []).push(s);
    });
    Object.keys(childrenByParent).forEach(function (k) {
      childrenByParent[k].sort(function (a, b) { return (a.paragraphIdx || 0) - (b.paragraphIdx || 0); });
    });
    function _renderTree(parentKey, depth) {
      var kids = childrenByParent[parentKey] || [];
      return kids.map(function (s) {
        var rangeStr = s.endParagraphIdx != null && s.endParagraphIdx !== s.paragraphIdx
          ? '<span class="_ti_pe_range">p' + s.paragraphIdx + '–p' + s.endParagraphIdx + '</span>'
          : '<span class="_ti_pe_range">p' + s.paragraphIdx + '</span>';
        var numChip = s.number
          ? '<span class="_ti_pe_num">' + _tiEsc(s.number) + '</span>'
          : '';
        var manualChip = s.isManual
          ? '<span class="_ti_pe_manual">MANUAL</span>'
          : '';
        var bmChip = '<code class="_ti_pe_bm">' + _tiEsc(s.bookmarkName || '') + '</code>';
        var indent = 'margin-left:' + (depth * 18) + 'px;';
        var row =
          '<div class="_ti_pe_row" style="' + indent + '">' +
            '<span class="_ti_pe_arrow">' + (childrenByParent[s.paragraphIdx] ? '▾' : '·') + '</span>' +
            rangeStr +
            numChip +
            '<span class="_ti_pe_title">' + _tiEsc(s.title || '(untitled)') + '</span>' +
            manualChip +
            bmChip +
          '</div>';
        return row + _renderTree(s.paragraphIdx, depth + 1);
      }).join('');
    }
    var treeHtml = _renderTree('_top', 0);
    var overlay = document.createElement('div');
    overlay.id = DIALOG_ID;
    overlay.style.cssText =
      'position:fixed;top:40px;left:50%;transform:translateX(-50%);' +
      'width:min(900px,95vw);max-height:calc(100vh - 80px);' +
      'background:#fff;border:1px solid #cbd5e1;border-radius:8px;' +
      'box-shadow:0 12px 40px rgba(15,23,42,0.25);' +
      'z-index:1100;display:flex;flex-direction:column;';
    overlay.innerHTML =
      '<div style="background:linear-gradient(135deg,#0d1b2a 0%,#1b263b 100%);color:#fff;padding:12px 16px;border-bottom:2px solid #c9a227;border-radius:7px 7px 0 0;display:flex;justify-content:space-between;align-items:center;">' +
        '<div>' +
          '<div style="font:800 9px/1 Inter,sans-serif;letter-spacing:1.4px;text-transform:uppercase;color:#c9a227;margin-bottom:3px;">DOWNSTREAM-TOOL VIEW</div>' +
          '<div style="font:700 16px/1.2 \'Book Antiqua\',Georgia,serif;">👁 Preview Export — ' + active.length + ' sections</div>' +
        '</div>' +
        '<button data-act="pe-close" style="background:transparent;border:1px solid rgba(255,255,255,0.3);color:#fff;padding:4px 10px;border-radius:4px;cursor:pointer;font:600 11px/1 Inter,sans-serif;">✕ Close</button>' +
      '</div>' +
      '<div style="padding:12px 16px;border-bottom:1px solid #e2e8f0;background:#f8fafc;font:500 11px/1.5 Inter,sans-serif;color:#475569;">' +
        '<b>What this is:</b> the exact map that Template Searcher, Build Draft, Ask ELI, and any future tool will see when they read this document\'s ELI_SEC_* bookmarks + metadata. ' +
        'Hierarchy comes from <code>parentBookmarkName</code>. Position from <code>paragraphIdx</code>/<code>endParagraphIdx</code>. Skipped sections are excluded.' +
      '</div>' +
      '<div style="display:flex;gap:0;border-bottom:1px solid #e2e8f0;background:#f1f5f9;">' +
        '<button data-act="pe-tab-tree" class="_ti_pe_tab _ti_pe_tab_active" style="flex:1;padding:10px;font:700 11px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;border:none;background:#fff;color:#0d1b2a;cursor:pointer;border-bottom:2px solid #c9a227;">🌲 Tree View</button>' +
        '<button data-act="pe-tab-json" class="_ti_pe_tab" style="flex:1;padding:10px;font:700 11px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;border:none;background:transparent;color:#64748b;cursor:pointer;">{ } JSON Payload</button>' +
      '</div>' +
      '<div id="' + DIALOG_ID + '_body_tree" style="flex:1;overflow:auto;padding:12px 16px;font:500 12px/1.5 Inter,sans-serif;">' +
        treeHtml +
      '</div>' +
      '<div id="' + DIALOG_ID + '_body_json" style="display:none;flex:1;overflow:auto;padding:12px 16px;">' +
        '<pre style="margin:0;font:500 11px/1.45 ui-monospace,Consolas,monospace;color:#0f172a;white-space:pre-wrap;word-break:break-all;">' + _tiEsc(JSON.stringify(jsonPayload, null, 2)) + '</pre>' +
      '</div>' +
      '<div style="padding:10px 16px;border-top:1px solid #e2e8f0;background:#f8fafc;display:flex;gap:8px;justify-content:flex-end;">' +
