        var parentIdx = parentSel ? Number(parentSel.value) : -1;
        var parent = (parentIdx >= 0) ? state.sections[parentIdx] : null;
        var parentArticle = parent
          ? { number: parent.number || "", title: parent.title || "", level: parent.level || 0 }
          : null;
        var ancestry = parent
          ? (parent.ancestry || []).concat([{ number: parent.number || "", title: parent.title || "" }])
          : [];
        var newLevel = parent ? ((parent.level || 0) + 1) : 1;
        // Build canonical slug name from title + parent's number. Falls
        // back to opaque ID only if title is empty / slug can't be built.
        // _refreshBookmarkNames() runs after push and will idempotently
        // re-derive the same slug (or fix it if anything drifts).
        var existingNames = {};
        state.sections.forEach(function (s) { if (s.bookmarkName) existingNames[s.bookmarkName] = true; });
        var bookmarkName;
        if (ttl || num) {
          bookmarkName = _tiBookmarkName(num, ttl, parent ? (parent.number || "") : "", existingNames);
        }
        if (!bookmarkName) {
          var idTries = 0;
          do {
            bookmarkName = "ELI_SEC_" + _tiGenSectionId();
            idTries++;
          } while (existingNames[bookmarkName] && idTries < 20);
        }
        var newSection = {
          paragraphIdx: firstIdx,
          endParagraphIdx: lastIdx,
          number: num,
          title: ttl,
          level: newLevel,
          parentArticle: parentArticle,
          parentSectionPidx: parent ? parent.paragraphIdx : null,
          ancestry: ancestry,
          originalNumber: num,
          originalTitle: ttl,
          bookmarkName: bookmarkName,
          skip: false,
          logicOnly: false,
          edited: false,
          isManual: true,
        };
        // Insert in correct position (sorted by paragraphIdx).
        var inserted = false;
        for (var i = 0; i < state.sections.length; i++) {
          if (state.sections[i].paragraphIdx > firstIdx) {
            state.sections.splice(i, 0, newSection);
            inserted = true;
            break;
          }
        }
        if (!inserted) state.sections.push(newSection);
        _sortSections();
        // Clear any prior ELI_SKIP_* markers in the new section's paragraph
        // range. Without this, a paragraph the user previously Removed
        // stays in skipPidxSet — and on rescan the new section gets
        // silently filtered out at the same body pidx the SKIP encodes.
        // Apply will then see the SKIP as orphan and try to delete its
        // bookmark from the doc; the rescan filter is name-based so it
        // tolerates a delete failure (bookmark.delete() isn't available on
        // every Word build).
        if (state.removedParagraphs) {
          for (var sp = firstIdx; sp <= lastIdx; sp++) {
            delete state.removedParagraphs[sp];
          }
        }
        // Re-derive canonical slug names across all sections — handles
        // the case where the new section's slug collides with a peer and
        // needs deduping via the standard _tiBookmarkName logic.
        _refreshBookmarkNames();
        state.selectedParagraphs = {};
        state.lastSelectedIdx = null;
        if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        if (typeof showToast === "function") {
          var msg = "✓ Manual section created";
          if (parent) {
            var plbl = (parent.number ? parent.number + " " : "") + (parent.title || "section");
            msg += " under " + plbl;
          }
          msg += " — click Save & Apply to write the range bookmark";
          showToast(msg, "ok");
        }
        _markDirty();
        _renderBody();
      }
    });
    // Esc to close
    overlay.addEventListener("keydown", function (ev2) {
      if (ev2.key === "Escape" && overlay.parentNode) overlay.parentNode.removeChild(overlay);
    });
  }
  out.oninput = function (ev) {
    var t = ev.target;
    if (!t || !t.getAttribute) return;
    var act = t.getAttribute("data-act");
    var idx = Number(t.getAttribute("data-idx"));
    var s = state.sections[idx];
    if (!s) return;
    if (act === "edit-number") {
      s.number = String(t.value || "").trim();
      s.editedAt = new Date().toISOString();
    } else if (act === "edit-title") {
      // Allow empty title — admin's intentional clear, value still tracked.
      s.title = String(t.value || "");
      s.editedAt = new Date().toISOString();
    } else {
      return;
    }
    _refreshBookmarkNames();
    _markDirty();
    // 2026-05-23: selective live-update of THIS section's map summary
    // (title text, bookmark chip, number badge) so the change is visible
    // immediately without re-rendering the whole map — preserves input
    // focus + caret position so admin can keep typing.
    var pgroup = out.querySelector('._ti_pgroup[data-section-idx="' + idx + '"]');
    if (pgroup) {
      var summary = pgroup.querySelector('summary._ti_map_summary');
      if (summary) {
        var titleSpan = summary.querySelector('._ti_map_title_text');
        if (titleSpan) titleSpan.textContent = s.title || "(untitled)";
        var bmCode = summary.querySelector('._ti_map_bm');
        if (bmCode && !s.skip) bmCode.textContent = s.bookmarkName;
        var numSpan = summary.querySelector('._ti_map_num');
        if (numSpan) {
          numSpan.classList.remove('_ti_map_num_inherited', '_ti_map_num_empty');
          if (s.number) {
            numSpan.textContent = s.number;
          } else if (s.parentArticle && s.parentArticle.number) {
            numSpan.textContent = s.parentArticle.number;
            numSpan.classList.add('_ti_map_num_inherited');
          } else {
            numSpan.textContent = '—';
            numSpan.classList.add('_ti_map_num_empty');
          }
        }
      }
    }
  };
  _scan();
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;
  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTemplateIndexer"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showTemplateIndexer !== "function") {
      eli.log.event("tool", "template_indexer_fn_missing", {});
      if (typeof showToast === "function") showToast("Template Indexer failed to load", "err");
      return;
    }
    try { window.showTemplateIndexer(); }
    catch (e) {
      eli.log.event("tool", "template_indexer_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }
  eli.register({
    tile: { app_template_indexer: _show },
    template_indexer: { open: _show },
  });
  eli.log.event("tool", "template_indexer_initialized", {});
}

